import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"ADR-0003: 为什么选择 JSON-RPC over stdio","description":"","frontmatter":{},"headers":[],"relativePath":"zh/adr/ADR-0003-why-jsonrpc-over-stdio.md","filePath":"zh/adr/ADR-0003-why-jsonrpc-over-stdio.md","lastUpdated":0}`),a={name:`zh/adr/ADR-0003-why-jsonrpc-over-stdio.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="adr-0003-为什么选择-json-rpc-over-stdio" tabindex="-1">ADR-0003: 为什么选择 JSON-RPC over stdio <a class="header-anchor" href="#adr-0003-为什么选择-json-rpc-over-stdio" aria-label="Permalink to “ADR-0003: 为什么选择 JSON-RPC over stdio”">​</a></h1><ul><li>状态：已接受</li><li>日期：2026-10-31</li><li>关联：docs/guide/agent-protocol.md，ADR-0002</li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to “背景”">​</a></h2><p>核心与插件子进程之间需要一条请求/响应通道，承载握手、能力声明、探测调用与恢复动作； 它必须对插件作者零门槛，且不能扩大攻击面。</p><h2 id="决策" tabindex="-1">决策 <a class="header-anchor" href="#决策" aria-label="Permalink to “决策”">​</a></h2><p>JSON-RPC 2.0 over stdio，行分隔（每行一个 JSON 消息）： stdout <strong>只</strong>承载协议，stderr <strong>只</strong>承载诊断日志（永不作协议解析）； 请求带 id 与超时；不完整行、异常 JSON、未知方法返回明确错误而非崩溃； stdout 行有长度上限，超限跳过而非致命；stderr 独立线程持续排空并截断保留尾部。</p><h2 id="替代方案" tabindex="-1">替代方案 <a class="header-anchor" href="#替代方案" aria-label="Permalink to “替代方案”">​</a></h2><ul><li><strong>gRPC/protobuf</strong>：强类型与流式好，但需要代码生成工具链，插件作者门槛高； 引入 HTTP/2 网络栈，复杂度与攻击面都大。</li><li><strong>HTTP on localhost</strong>：暴露端口（本机其他进程可访问）；生命周期绑定复杂。</li><li><strong>自定义二进制协议</strong>：解析器要自己维护，崩溃面大，调试困难。</li></ul><h2 id="优缺点" tabindex="-1">优缺点 <a class="header-anchor" href="#优缺点" aria-label="Permalink to “优缺点”">​</a></h2><p>优点：任何语言三行代码即可说话；无端口、无网络面；stdout/stderr 语义分界让 &quot;协议被日志污染&quot;类故障可观测、可防（上限 + 跳过策略）。 缺点：吞吐低于二进制协议（对告警量级完全够用）；行协议要求插件严格保证 stdout 纪律——所以宿主侧还要防御性处理不守纪律的插件。</p><h2 id="后续影响" tabindex="-1">后续影响 <a class="header-anchor" href="#后续影响" aria-label="Permalink to “后续影响”">​</a></h2><ul><li>session.rs：读循环、deadline、取消、输出上限、dying-words（崩溃时 stderr 尾部）。</li><li>出站请求（宿主→插件方向）有大小上限，防止宿主被诱导写满管道。</li></ul>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};